export function requestDog(world,car=world.cars[0]){const candidates=world.crossings.map(c=>({c,d:directedDistance(car.s,c.s,car.direction)})).filter(v=>v.d>35&&v.d<240).sort((a,b)=>a.d-b.d);const c=candidates[0]?.c||world.crossings[0];world.dogEvent={crossing:c.id,start:world.time};event(world,`Dog crossing requested at ${c.name}`);}
export function trafficSummary(world){const s=world.stats;return{time:world.time,cars:world.cars.length,controller:world.mode,supervisor:world.supervisor,seed:world.seed,...s,distanceKm:s.distance/1000,score:Math.round(clamp(100-25*s.vehicleContacts-60*s.vulnerableContacts-10*s.redLights-.1*s.laneSeconds-.05*s.speedSeconds-.03*s.unsafeSeconds,0,100))};}
